import numpy as np, sys
sys.setrecursionlimit(10000)
g=np.array(demo_out)==4
seen=np.zeros_like(g)
comps=[]
for r in range(20):
    for c in range(20):
        if g[r,c] and not seen[r,c]:
            stack=[(r,c)]; seen[r,c]=1; comp=[]
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+dx,b+dy
                    if 0<=x<20 and 0<=y<20 and g[x,y] and not seen[x,y]:
                        seen[x,y]=1; stack.append((x,y))
            comps.append(comp)
print(len(comps), [len(c) for c in comps])
for comp in sorted(comps,key=len,reverse=True)[:6]:
